    static boolean Last_Ocuu(long[] a, int n, long v) {
        int sta = 1, end = n - 1;
        while (sta <= end) {
            int mid = (sta + end) >> 1;
            if (a[mid] == v) {
                return true;
            } else if (a[mid] > v) {
                end = mid - 1;
            } else {
